<template>
    <div class="layout-px-spacing">  
        <div class="d-flex me-4 mt-2 ">
            <h3>Registered Devices</h3>
                        <div class="ms-auto">
                            <button class="btn btn-primary " @click="view_notification =! view_notification">                           
                                <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" fill="currentColor" class="bi bi-plus-square" viewBox="0 0 16 16">
  <path d="M14 1a1 1 0 0 1 1 1v12a1 1 0 0 1-1 1H2a1 1 0 0 1-1-1V2a1 1 0 0 1 1-1zM2 0a2 2 0 0 0-2 2v12a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V2a2 2 0 0 0-2-2z"/>
  <path d="M8 4a.5.5 0 0 1 .5.5v3h3a.5.5 0 0 1 0 1h-3v3a.5.5 0 0 1-1 0v-3h-3a.5.5 0 0 1 0-1h3v-3A.5.5 0 0 1 8 4"/>
</svg>
</button>
 
                        </div>
                    </div>



       
              <!-- loading spinner starts -->
        <div v-if="loading_spinner" v-html="tableShimmer()"></div>
        <!-- Loading spinner ends -->
        <div v-else class="row layout-top-spacing">
            <div class="col-xl-12 col-lg-12 col-sm-12 layout-spacing">
                <div class="panel p-0">
                    <div class="custom-table table3">
                        <v-client-table :data="notification" :columns="columns" :options="table_option">
                            <template #actions="props">
                              
                                <a href="javascript:;" class="edit me-3" @click="openEditModal(props.row)" data-bs-toggle="modal" :data-bs-target="'#edit-device'">
                                    <i class="bi bi-pencil-square fs-5 text-dark"></i>
                                </a>

                                  <a href="javascript:;" class="edit me-3" title="Test Notification" @click="testNotification(props.row)">
                                    <i class="bi bi-check fs-5 text-success"></i>
                                </a>

                                                <a 
                v-if="user_permissions.includes('can_delete_notification')"
                href="javascript:void(0);" @click="deletenotification(props.row)" class="text-danger">
<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" fill="currentColor" class="bi bi-trash" viewBox="0 0 16 16">
  <path d="M5.5 5.5A.5.5 0 0 1 6 6v6a.5.5 0 0 1-1 0V6a.5.5 0 0 1 .5-.5m2.5 0a.5.5 0 0 1 .5.5v6a.5.5 0 0 1-1 0V6a.5.5 0 0 1 .5-.5m3 .5a.5.5 0 0 0-1 0v6a.5.5 0 0 0 1 0z"/>
  <path d="M14.5 3a1 1 0 0 1-1 1H13v9a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V4h-.5a1 1 0 0 1-1-1V2a1 1 0 0 1 1-1H6a1 1 0 0 1 1-1h2a1 1 0 0 1 1 1h3.5a1 1 0 0 1 1 1zM4.118 4 4 4.059V13a1 1 0 0 0 1 1h6a1 1 0 0 0 1-1V4.059L11.882 4zM2.5 3h11V2h-11z"/>
</svg>
                </a>
                            </template>
                        </v-client-table>
                    </div>
                </div>
            </div>
        </div>

        <!-- Edit notification modal starts -->
<div class="modal fade mymodal" id="edit-device" data-bs-backdrop="false" data-bs-keyboard="false" tabindex="-1" aria-labelledby="editnotificationModalLabel" aria-hidden="true">
  <div class="modal-dialog modal-xl">
    <div class="modal-content">
      <div class="modal-header">
        <h1 class="modal-title fs-5" id="editnotificationModalLabel">EDIT NOTIFICATION MASTER</h1>
        <button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close" @click="closeEditModal()" id="close-btn"></button>
      </div>
      <form @submit.prevent="updateDevice()">
        <div class="modal-body">
            <div class="row mb-3">
                <div class="col-md-4">
                <label for="name">Device Name</label>
            <label class="form-control">{{ device.device_name }}</label>
            </div>

             <div class="col-md-4">
                <label for="name">Platform</label>
              <label class="form-control">{{ device.platform }}</label>
            </div>

            
             <div class="col-md-4">
                <label for="name">Included Users</label>
                                <multiselect 
                    v-model="device.user"
                    track-by="id"
                    :options= "users"
                    label = "name"
                    placeholder="Select Receivers"
                    :searchable = "true"        
                    :multiple="false"
                    :allow-empty ="false"
                    />
            </div>

          </div>
        </div>
        <div class="modal-footer">
          <button type="button" class="btn btn-secondary" data-bs-dismiss="modal" @click="closeEditModal()" id="close_editing">Close</button>
          <button type="submit" class="btn btn-primary" :disabled="loading_spinner">
            <span v-if="loading_spinner" class="spinner-border spinner-border-sm text-white me-2" role="status"></span>
           <span v-else> Edit</span>
          </button>
        </div>
      </form>
    </div>
  </div>
</div>
<!-- Edit notification modal ends -->


    </div>



    
</template>


<script setup>
    import { onMounted, ref, inject,watch } from 'vue';
    import axios from 'axios';
    import { useMeta } from '@/composables/use-meta';
    import Multiselect from '@suadelabs/vue3-multiselect';
    import '@suadelabs/vue3-multiselect/dist/vue3-multiselect.css';
    
    useMeta({ title: 'Notification Settings' });  
    const showConfirmation = inject('showConfirmation');
    const showMessage = inject('showMessage');
    const view_notification = ref(false);
    const showError = inject('showError');
    const user_permissions = JSON.parse(localStorage.getItem("user")).permissions;
    const formatDate = inject('formatDate');
    const tableShimmer = inject('tableShimmer');
    const loadingSpinner = inject('loadingSpinner'); 
    
    const loading_spinner = ref(false);
    const columns = ref(['SNo','owner','device','platform','registered_date','last_used','actions']);    
    const name = ref('');
    const description = ref('')
    const receivers = ref([]);
    const users = ref([])
    const notification = ref([]);
    const view_notification_id = ref('');

    
    const table_option = ref({
        perPage: 20,
        perPageValues: [20, 50 ,100],
        skin: 'table table-hover table-striped',
        columnsClasses: { actions: 'actions text-center' },
        sortable: ['SNo', 'name','short_name','status'],
        sortIcon: {
            base: 'sort-icon-none',
            up: 'sort-icon-asc',
            down: 'sort-icon-desc',
        },
        pagination: { nav: 'scroll', chunk: 5 },
        texts: {
            count: 'Showing {from} to {to} of {count}',
            filter: '',
            filterPlaceholder: 'Search...',
            limit: 'Results:',
        },
        resizableColumns: false,
    });

    const axiosInstance = axios.create({
        baseURL: process.env.VUE_APP_API_BASE_URL
    });

 

    const getDevices = async () => {
        loading_spinner.value = true;
        try {
            const response = await axiosInstance.get('notifications/live/registered-devices');
            notification.value = response.data.map((item, index) => ({
                ...item,
                SNo: index + 1,
                device: item.device_model,
                owner : item.user.name,
                last_used : item.last_used_at,
                registered_date : formatDate(item.created_at)
            }));
        } catch (error) {
            showError(error.message);
        }finally{
            loading_spinner.value = false;
        }
    };
    
    const sendNotification = inject('sendNotification')
    const testNotification = (row) => {
        sendNotification(' Notification Testing','Testing Notifications to ' +row.owner,[8,row.user.id])
        showMessage('Notification Sent')
    }



    const resetForm = () => {
    name.value = '';
    description.value = ''
};

const device = ref({
    id : '',
    user : '',
    platform : '',
    device_name : ''
})
    const updateDevice = async (id) => {
        loading_spinner.value = true;
        const payload = {
            id : device.value.id,
            user_id : device.value.user.id,
        };
        try {
            const response = await axiosInstance.post(`/notifications/live/registered-devices`, payload);
          
            getDevices();
            showMessage('Device updated !');
            closeEditModal();
        } catch (error) {
            showError(error.message);
        } finally {
            loading_spinner.value = false;
        }
    };

    const selectedNotification = ref('')
    const openEditModal =  (row) => {
     getUsers()

     device.value = {
        id : row.id,
        user :  row.user,
        device_name : row.device,
        platform : row.platform
     }
    };


    const getUsers = async ()=>{
        const response = await axiosInstance.get('users')
        users.value =  response.data 
    }
    const closeEditModal = () => {
        name.value = '';
        document.getElementById('close-btn').click()
    };

    const deletenotification = async (row) => {
  const res = await showConfirmation(
    'Delete Record',
    'Are you sure you want to delete notification. ' + row.name,
    `/approval-lists/${row.id}?deleted=1`,
    'put'
  );
  
  if (res?.refresh) {
    getDevices();
  }
};


const props = defineProps({
    activeTab: String
});

watch(
    () => props.activeTab,
    (tab) => {
        if (tab === 'devices') {
            getDevices();
        }
    }
);



</script>